const listEl = document.getElementById("list");
const countEl = document.getElementById("resultCount");

function haystack(b){ return [b.title,b.desc,b.note,(b.tags||[]).join(" "),b.url,b.domain].join(" ").toLowerCase(); }

// --- query language: words, "phrases", #labels, AND/OR/NOT, parentheses ---
function tokenize(q){
  const toks=[]; let i=0; const stop=' \t()"';
  while(i<q.length){
    const c=q[i];
    if(c===' '||c==='\t'){ i++; continue; }
    if(c==='('){ toks.push({t:'('}); i++; continue; }
    if(c===')'){ toks.push({t:')'}); i++; continue; }
    if(c==='"'){ let j=i+1,s=""; while(j<q.length&&q[j]!=='"'){ s+=q[j]; j++; } i=(j<q.length)?j+1:j; toks.push({t:'TERM',kind:'phrase',v:s}); continue; }
    if(c==='#'){ let j=i+1,s=""; if(q[j]==='"'){ j++; while(j<q.length&&q[j]!=='"'){ s+=q[j]; j++; } i=(j<q.length)?j+1:j; } else { while(j<q.length&&!stop.includes(q[j])){ s+=q[j]; j++; } i=j; } toks.push({t:'TERM',kind:'label',v:s}); continue; }
    let j=i,s=""; while(j<q.length&&!stop.includes(q[j])){ s+=q[j]; j++; } i=j;
    if(s==='AND') toks.push({t:'AND'});
    else if(s==='OR') toks.push({t:'OR'});
    else if(s==='NOT') toks.push({t:'NOT'});
    else toks.push({t:'TERM',kind:'word',v:s});
  }
  return toks;
}
function parse(toks){
  let p=0; const peek=()=>toks[p], eat=()=>toks[p++];
  function pOr(){ let l=pAnd(); while(peek()&&peek().t==='OR'){ eat(); l={op:'or',l,r:pAnd()}; } return l; }
  function pAnd(){ let l=pNot(); while(peek()&&(peek().t==='AND'||peek().t==='TERM'||peek().t==='('||peek().t==='NOT')){ if(peek().t==='AND') eat(); l={op:'and',l,r:pNot()}; } return l; }
  function pNot(){ if(peek()&&peek().t==='NOT'){ eat(); return {op:'not',c:pNot()}; } return pPrim(); }
  function pPrim(){ const tk=peek(); if(!tk) throw new Error("end"); if(tk.t==='('){ eat(); const e=pOr(); if(peek()&&peek().t===')') eat(); else throw new Error(")"); return e; } if(tk.t==='TERM'){ eat(); return {op:'term',kind:tk.kind,v:tk.v}; } throw new Error("tok"); }
  const ast=pOr(); if(p!==toks.length) throw new Error("trailing"); return ast;
}
function evalAst(n,b,h){
  if(n.op==='or') return evalAst(n.l,b,h)||evalAst(n.r,b,h);
  if(n.op==='and') return evalAst(n.l,b,h)&&evalAst(n.r,b,h);
  if(n.op==='not') return !evalAst(n.c,b,h);
  if(n.op==='term'){ if(n.kind==='label') return (b.tags||[]).some(t=>t.toLowerCase()===n.v.toLowerCase()); return h.includes((n.v||"").toLowerCase()); }
  return false;
}
function collectHl(n,neg,out){ if(!n) return; if(n.op==='or'||n.op==='and'){ collectHl(n.l,neg,out); collectHl(n.r,neg,out); } else if(n.op==='not'){ collectHl(n.c,!neg,out); } else if(n.op==='term'){ if(!neg&&n.v) out.push(n.v.toLowerCase()); } }

let ast=null, astError=false, hlTerms=[];
function buildQuery(){
  ast=null; astError=false; hlTerms=[];
  const q=query.trim(); if(!q) return;
  try{ ast=parse(tokenize(q)); const out=[]; collectHl(ast,false,out); hlTerms=[...new Set(out.filter(Boolean))]; }
  catch(e){ astError=true; hlTerms=q.toLowerCase().split(/\s+/).filter(w=>!['and','or','not'].includes(w)); }
}
function matches(b){
  const q=query.trim(); if(!q) return true; const h=haystack(b);
  if(ast&&!astError){ try{ return evalAst(ast,b,h); }catch(e){} }
  return q.toLowerCase().split(/\s+/).filter(Boolean).every(x=>h.includes(x));
}
function hl(text){
  let out=esc(text);
  hlTerms.forEach(t=>{ if(!t) return; const re=new RegExp("("+t.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","ig"); out=out.replace(re,'<span class="hl">$1</span>'); });
  return out;
}

function render(){
  if(!bookmarks.length){
    countEl.textContent="";
    listEl.innerHTML = '<div class="empty"><div class="big">Nothing saved yet.</div><div>Paste a link above to keep your first one.</div></div>';
    return;
  }
  const filtered = bookmarks.filter(matches);
  if(query.trim()){
    countEl.textContent = filtered.length===1 ? "1 match" : filtered.length+" matches";
  } else { countEl.textContent=""; }

  if(!filtered.length){
    listEl.innerHTML = `<div class="no-results"><div class="big">No bookmarks match “${esc(query)}”.</div><div>Try a different word, topic, or label.</div></div>`;
    return;
  }

