.note-preview-label { font-size: 11px; color: var(--muted); margin-top: 8px; }
.note-preview { font-size: 13px; color: #55554e; background: #fbfbf9; border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; margin-top: 4px; }
