output.text:
:root {
  --bg: #f7f7f5; --card: #ffffff; --ink: #2b2b2b; --muted: #9a9a92;
  --line: #e7e7e2; --accent: #4a6b57; --accent-soft: #e9f0ec; --chip: #eef0ee;
}
* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--ink); line-height: 1.5; }
.wrap { max-width: 760px; margin: 0 auto; padding: 28px 20px 90px; }
header h1 { font-size: 22px; font-weight: 600; margin: 0 0 2px; letter-spacing: -0.01em; }
.tagline { margin: 0 0 12px; color: var(--muted); font-size: 14px; }

.tools-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 14px; }
.tools-status { font-size: 12.5px; color: var(--muted); }
.ghost-btn { border: 1px solid var(--line); background: #fff; border-radius: 8px; padding: 6px 10px; font-size: 12.5px; color: #6a6a63; cursor: pointer; }
.ghost-btn.active { background: #2b2b2b; color: #fff; border-color: #2b2b2b; }

.display-panel { background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 12px 16px; margin-bottom: 16px; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.dp-row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; padding: 6px 0; }
.dp-label { font-size: 13px; color: #55554e; min-width: 90px; }

.save-bar { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px; display: flex; gap: 10px; align-items: center; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.save-bar input { flex: 1; border: none; outline: none; font-size: 15px; background: transparent; color: var(--ink); }
.btn { border: none; border-radius: 10px; padding: 10px 16px; font-size: 14px; font-weight: 500; cursor: pointer; background: var(--accent); color: #fff; white-space: nowrap; }
.btn.secondary { background: var(--chip); color: var(--ink); }
.url-note { font-size: 12.5px; color: #a84a4a; margin-top: 8px; }

.search-bar { display: flex; align-items: center; gap: 8px; margin-top: 16px; background: #fff; border: 1px solid var(--line); border-radius: 12px; padding: 10px 14px; box-shadow: 0 1px 2px rgba(0,0,0,.03); }
.search-bar svg { width: 16px; height: 16px; color: var(--muted); flex: none; }
.search-bar input { flex: 1; border: none; outline: none; font-size: 14.5px; background: transparent; color: var(--ink); }
.search-clear { border: none; background: transparent; color: var(--muted); cursor: pointer; font-size: 13px; }

.collections { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-top: 12px; }
.collections .lbl { font-size: 11.5px; color: var(--muted); }
.collections .coll { display: inline-flex; align-items: center; gap: 7px; background: #eef2ef; border: 1px solid #dbe3dd; color: #3f5a4a; border-radius: 999px; padding: 5px 11px; font-size: 12.5px; cursor: pointer; }
.collections .coll.active { background: var(--accent); color: #fff; border-color: var(--accent); }
.collections .coll .del { color: #9aa79f; font-weight: 700; cursor: pointer; }
.collections .coll.active .del { color: #cfe0d6; }
.collections .save-coll { background: transparent; border: 1px dashed #c6cec8; color: #6a6a63; border-radius: 999px; padding: 5px 11px; font-size: 12.5px; cursor: pointer; }
.collections input { border: 1px solid var(--line); border-radius: 8px; padding: 5px 9px; font-size: 13px; }
.collections .mini { border: none; background: var(--accent); color: #fff; border-radius: 8px; padding: 5px 10px; font-size: 12.5px; cursor: pointer; }
.collections .mini.ghost { background: transparent; color: var(--muted); text-decoration: underline; }

.controls-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 16px; }
