.result-count { font-size: 12px; color: var(--muted); margin: 14px 2px 0; }

.list { margin-top: 10px; display: flex; flex-direction: column; gap: 12px; }
.item { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px 16px; box-shadow: 0 1px 2px rgba(0,0,0,.03); display: flex; gap: 14px; align-items: flex-start; }
