.selbox.on { background: var(--accent); border-color: var(--accent); }
.thumb { width: 82px; min-width: 82px; height: 60px; border-radius: 8px; overflow: hidden; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 12px; font-weight: 600; text-align: center; object-fit: cover; }
img.thumb { object-fit: cover; }
